async fn function0(n:i64,seed:i64)->i64{let directory=std::env::var("TSRUST_COMPRESSION_INPUT_DIR").unwrap();let payload=std::fs::read(format!("{directory}/random-{seed}-raw.bin")).unwrap();let pool=tsrust_native_threads::create_pool(1,1).unwrap();let mut sum=0;for _ in 0..if n== -1{1}else{n}{let input=payload.clone();let path=format!("{directory}/working-compression_inflateraw_writer_random.bin");let sink=tsrust_native_io::Writer::file(tsrust_native_files::fs::create(&path).unwrap());let mut transformed=tsrust_native_compression_streams::TransformWriter::new(sink,pool.submission(),tsrust_native_compression::Format::Raw,tsrust_native_compression::Direction::Decode,None,None).unwrap();if transformed.write_all(&input).await.is_err(){panic!("stream failure");}let sink=match transformed.finish().await{Ok(value)=>value,Err(_)=>panic!("finish failure")};sink.close().await.unwrap();let output=std::fs::read(&path).unwrap();std::fs::remove_file(&path).unwrap();if n== -1{std::fs::write(std::env::var("TSRUST_COMPRESSION_PROBE_OUTPUT").unwrap(),&output).unwrap();pool.shutdown().unwrap();return output.len()as i64;}assert_eq!(output.len(),16384);for value in output{sum=(sum*131+i64::from(value))%1000000007;}}pool.shutdown().unwrap();sum}fn main(){}
